package com.javacodingagent.bootstrap.security;
import com.javacodingagent.common.web.ApiResponse; import org.springframework.beans.factory.annotation.Value; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController { private final JwtService jwt; private final String user; private final String password; public AuthController(JwtService jwt, @Value("${coding-agent.security.admin-username:}") String user, @Value("${coding-agent.security.admin-password:}") String password) { this.jwt = jwt; this.user = user; this.password = password; } @PostMapping("/token") ApiResponse<?> token(@RequestBody Login request) { if (user.isBlank() || password.isBlank() || !user.equals(request.username()) || !password.equals(request.password())) return ApiResponse.failure("AUTHENTICATION_FAILED", "Invalid credentials"); return ApiResponse.ok(Map.of("accessToken", jwt.issue(user), "tokenType", "Bearer")); } record Login(String username, String password) { } }
